head.script:
scwin.screenId = "jldods16500";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_15", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_when_17", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '2'); } }, { id: "c_otherwise_19", fn: function(){ return (!(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1') || ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '2'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.tab('list');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods16500.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_tab_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_tab_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_tab_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.tab('list')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.btn_tab_onclick' }); }
};

