*/
scwin.btn_window_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_window_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16500.btn_window_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_search_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_search_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fn_search_ajaxsubmit",
        method: "post",
        action: "/sprtroom/schedule.do",
        ref: "dma_searchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods16500.tx_fn_search_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.tab
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_displayDiv
 * @returns
 * @hidden N
*/
scwin.tab = async function (ipt_displayDiv) {
    /* sdd-asis-lifecycle:begin fn_tab — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_displayDiv', $('#searchForm')).val(ipt_displayDiv);
    await scwin.search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.yearChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.yearChange = async function () {
    /* sdd-asis-lifecycle:begin fn_yearChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.monthChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_month
 * @returns
 * @hidden N
*/
scwin.monthChange = async function (ipt_month) {
    /* sdd-asis-lifecycle:begin fn_monthChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#monthListArea").children("a").each(function(i) {
            $(this).removeClass();
            if ((i + 1) === Number(ipt_month)) {
                $(this).addClass("active");
            }
    });
    $('#ipt_month', $('#searchForm')).val(ipt_month);
    await scwin.search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods16500/jldods16500.xml");
    $('#ipt_method', $('#searchForm')).val("findDisclosureSchedules");
    await scwin.tx_fn_search_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.searchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fn_searchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($('#ipt_displayDiv', $('#searchForm')).val() === "list") {
        $("#cal_list", $('#searchForm')).empty().html(data).trigger("create");
    } else {
        $("#cal_view", $('#searchForm')).empty().html(data).trigger("create");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findSchedule1
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_calndDd ipt_byddSeq
 * @returns
 * @hidden N
*/
scwin.findSchedule1 = function (ipt_calndDd, ipt_byddSeq) {
    /* sdd-asis-lifecycle:begin fn_findSchedule1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const disclosureSchedulePop = $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/sprtroom/schedule.do?method=findDisclosureSchedule1&calndDd=" + ipt_calndDd + "&byddSeq=" + ipt_byddSeq + ""), { id: "공시일정상세", scrollbars: false, width: "500", height: "320", resizable: true, type: "pageFramePopup" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findSchedule2
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_acptNo ipt_schdlAdmItmTpCd ipt_byddSeq
 * @returns
 * @hidden N
*/
scwin.findSchedule2 = function (ipt_acptNo, ipt_schdlAdmItmTpCd, ipt_byddSeq) {
    /* sdd-asis-lifecycle:begin fn_findSchedule2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const disclosureSchedulePop = $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/sprtroom/schedule.do?method=findDisclosureSchedule2&acptNo=" + ipt_acptNo + "&schdlAdmItmTpCd=" + ipt_schdlAdmItmTpCd + "&byddSeq=" + ipt_byddSeq + ""), { id: "공시일정상세", scrollbars: false, width: "500", height: "350", resizable: true, type: "pageFramePopup" }, {});
    /* sdd-asis-lifecycle:end */
};
